import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import path from 'path'
import { fileURLToPath } from 'url'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)
const projectRoot = path.resolve(__dirname, '..')

// src/data.json (generated by generate_manifest.js) holds absolute /@fs/<path of the generating machine>/...
// URLs. This plugin rewrites them to this checkout's oasis_data and adni_data, so the same manifest works on
// any machine and inside Docker (repository mounted at /app) without regenerating it.
const rebaseDataUrls = () => ({
  name: 'rebase-data-urls',
  configureServer(server) {
    server.middlewares.use((req, _res, next) => {
      req.url = req.url.replace(/^\/@fs\/.*?\/(oasis_data|adni_data|dummy_data)\//, `/@fs${projectRoot}/$1/`)
      next()
    })
  },
})

// Vite configuration: React plugin, URL rebasing, and file-system access to the data folders
export default defineConfig({
  plugins: [react(), rebaseDataUrls()],
  server: {
    fs: {
      strict: false,
      allow: [
        projectRoot,
        path.join(projectRoot, 'oasis_data'),
        path.join(projectRoot, 'adni_data'),
        path.join(projectRoot, 'dummy_data'),
        path.join(projectRoot, 'alzheimer-xai-cdss')
      ]
    }
  }
})
